/**
 * Map legacy PNG filenames and icon keys to icon keys.
 *
 * @return array<string, string>
 */
function site_blocks_icon_legacy_map(): array {
	return array(
		// Ajax hero / CTA PNGs.
		'wifi'                => 'wifi',
		'app'                 => 'layout-grid',
		'shield'              => 'shield-check',
		'wired'               => 'cable',
		'hub'                 => 'cpu',
		'jeweller'            => 'radio',
		'4g'                  => 'signal',
		'dollar'              => 'circle-dollar-sign',
		'technician'          => 'user-cog',
		'secure'              => 'lock',
		'australia-map'       => 'map',
		'call'                => 'phone',
		// CCTV / intercom / access PNGs.
		'ip-camera'           => 'cctv',
		'remote-app'          => 'smartphone',
		'access-control'      => 'lock-smart',
		'smart-detection'     => 'scan-eye',
		'weatherproof'        => 'cloud-rain',
		'property-coverage'   => 'map-pin',
		'home-camera'         => 'house',
		'support'             => 'headset',
		'alarm-systems'       => 'bell-ring',
		'night-vision'        => 'moon',
		// Related services.
		'back-to-base'        => 'headset',
		'virtual-patrol'      => 'eye',
		'cctv'                => 'cctv',
		'mobile-patrols'      => 'car',
		// Scenario grid keys.
		'construction'        => 'hard-hat',
		'farm-rural'          => 'tractor',
		'fence-perimeter'     => 'fence',
		'warehouse-yard'      => 'warehouse',
		// Monitoring package / communicator keys.
		'power'               => 'zap',
		'backup'              => 'battery-charging',
		'detection'           => 'scan-eye',
		'camera'              => 'cctv',
		'connectivity'        => 'wifi',
		'weather'             => 'cloud-rain',
		'mobile'              => 'smartphone',
		'router'              => 'router',
	);
}

/**
 * Render an icon as inline SVG.
 *
 * @param string $name        Icon key (see site_blocks_icon_paths()).
 * @param int    $size        Deprecated, sizing is controlled via CSS (--sg-icon-size).
 * @param string $extra_class Optional extra CSS class(es).
 */
function site_blocks_icon( string $name, int $size = 24, string $extra_class = '' ): void {
	$paths = site_blocks_icon_paths();
	$path  = $paths[ $name ] ?? '';

	if ( '' === $path ) {
		echo '<span class="sg-ajax-hero__icon-placeholder" aria-hidden="true"></span>';
		return;
	}

	$class = 'sg-icon';
	if ( '' !== $extra_class ) {
		$class .= ' ' . $extra_class;
	}

	printf(
		'<svg class="%s" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false"><path d="%s"/></svg>',
		esc_attr( $class ),
		esc_attr( $path )
	);
}

/**
 * Render an icon from a legacy PNG filename or icon key.
 *
 * @param string $key  Filename (e.g. wifi.png) or icon key (e.g. back-to-base).
 * @param int    $size Deprecated, sizing is controlled via CSS (--sg-icon-size).
 */
function site_blocks_icon_from_legacy( string $key, int $size = 24 ): void {
	$key = strtolower( trim( $key ) );
	$key = preg_replace( '/\.png$/', '', $key ) ?? $key;

	$map   = site_blocks_icon_legacy_map();
	$paths = site_blocks_icon_paths();
	$name  = $map[ $key ] ?? $key;

	if ( ! isset( $paths[ $name ] ) ) {
		echo '<span class="sg-ajax-hero__icon-placeholder" aria-hidden="true"></span>';
		return;
	}

	site_blocks_icon( $name, $size );
}
